-- ============================================================
-- 001_initial_schema.sql — consolidated baseline
--
-- The platform has never been deployed, so every incremental migration that
-- accumulated during development carries no history worth preserving. This
-- file is the resulting end state, generated by applying every migration in
-- order to a clean database and dumping the result, so it is equivalent by
-- construction rather than by hand.
--
-- Structure: extensions → schema, types, tables, constraints, indexes, triggers
-- → seed data → least-privilege roles and grants.
--
-- Run through packages/db/src/migrate.ts (node-pg), so it contains no psql
-- backslash meta-commands.
-- ============================================================

-- ── Extensions (citext is used by resource_types.code and others) ───────────
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS citext;

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

