--
-- Name: notify_sse_job(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.notify_sse_job() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.status IS DISTINCT FROM NEW.status THEN
    PERFORM pg_notify('sse_events', json_build_object(
      'type', 'job',
      'kind', TG_ARGV[0],
      'id', NEW.id,
      'status', NEW.status
    )::text);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: notify_sse_notification(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.notify_sse_notification() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM pg_notify('sse_events', json_build_object(
    'type', 'notification',
    'user_id', NEW.recipient_user_id,
    'id', NEW.id,
    'severity', NEW.severity,
    'title', NEW.title
  )::text);
  RETURN NEW;
END;
$$;


--
-- Name: prevent_artifact_content_mutation(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.prevent_artifact_content_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.bucket_name IS DISTINCT FROM NEW.bucket_name
       OR OLD.object_key IS DISTINCT FROM NEW.object_key
       OR OLD.checksum IS DISTINCT FROM NEW.checksum
       OR OLD.file_size_bytes IS DISTINCT FROM NEW.file_size_bytes
       OR OLD.owner_type_code IS DISTINCT FROM NEW.owner_type_code
       OR OLD.owner_id IS DISTINCT FROM NEW.owner_id
       OR OLD.artifact_type_code IS DISTINCT FROM NEW.artifact_type_code
       OR OLD.filename IS DISTINCT FROM NEW.filename
    THEN
        RAISE EXCEPTION 'artifact content columns are immutable';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: prevent_audit_mutation(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.prevent_audit_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'audit logs are append-only';
END;
$$;


