--

CREATE TABLE app.training_datasets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    description text,
    dataset_type_id uuid NOT NULL,
    task_type app.dataset_task_type NOT NULL,
    status text DEFAULT 'ACTIVE'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by_user_id uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by_user_id uuid,
    archived_at timestamp with time zone,
    row_version integer DEFAULT 1 NOT NULL,
    source_dataset_ids uuid[],
    version_number integer DEFAULT 1,
    split_strategy text,
    random_seed bigint,
    train_ratio numeric(6,5),
    val_ratio numeric(6,5),
    test_ratio numeric(6,5),
    storage_mode text,
    train_count bigint DEFAULT 0,
    val_count bigint DEFAULT 0,
    test_count bigint DEFAULT 0,
    class_count integer DEFAULT 0,
    classes_hash text DEFAULT ''::text,
    configuration_hash text DEFAULT ''::text,
    data_yaml_artifact_id uuid,
    manifest_artifact_id uuid,
    build_job_id uuid,
    failure_code text,
    failure_message text,
    build_started_at timestamp with time zone,
    build_finished_at timestamp with time zone,
    ready_at timestamp with time zone,
    same_split_targets jsonb,
    relative_path text,
    origin text DEFAULT 'BUILT'::text NOT NULL,
    CONSTRAINT chk_training_datasets_name CHECK ((name ~ '^[a-zA-Z0-9_-]{1,255}$'::text)),
    CONSTRAINT chk_training_datasets_origin CHECK ((origin = ANY (ARRAY['BUILT'::text, 'REGISTERED'::text]))),
    CONSTRAINT chk_training_datasets_registered_path CHECK (((origin <> 'REGISTERED'::text) OR (relative_path IS NOT NULL)))
);


