    preparing_at timestamp with time zone,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    locked_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    cancelled_by_user_id uuid,
    stop_requested_at timestamp with time zone,
    stop_requested_by_user_id uuid,
    stopped_at timestamp with time zone,
    failure_code text,
    failure_message text,
    result_model_id uuid,
    parent_job_id uuid,
    resume_source_job_id uuid,
    cloned_from_job_id uuid,
    experiment_id uuid,
    job_group_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by_user_id uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by_user_id uuid,
    row_version integer DEFAULT 1 NOT NULL,
    configuration_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    submitted_at timestamp with time zone,
    failure_stage text,
    training_dataset_id uuid,
    CONSTRAINT chk_training_clone_source CHECK (((cloned_from_job_id IS NULL) OR (cloned_from_job_id <> id))),
    CONSTRAINT chk_training_config_version CHECK ((configuration_version >= 1)),
    CONSTRAINT chk_training_parent CHECK (((parent_job_id IS NULL) OR (parent_job_id <> id))),
    CONSTRAINT chk_training_resume_source CHECK (((resume_source_job_id IS NULL) OR (resume_source_job_id <> id)))
);


