-- Name: uq_active_scan_per_source; Type: INDEX; Schema: app; Owner: -
--

CREATE UNIQUE INDEX uq_active_scan_per_source ON app.source_dataset_scans USING btree (source_dataset_id) WHERE (status = ANY (ARRAY['PENDING'::app.dataset_scan_status, 'RUNNING'::app.dataset_scan_status]));


--
-- Name: uq_dataset_type_child_name; Type: INDEX; Schema: app; Owner: -
--

CREATE UNIQUE INDEX uq_dataset_type_child_name ON app.dataset_types USING btree (parent_id, lower(name)) WHERE (parent_id IS NOT NULL);


--
-- Name: uq_dataset_type_root_name; Type: INDEX; Schema: app; Owner: -
--

CREATE UNIQUE INDEX uq_dataset_type_root_name ON app.dataset_types USING btree (lower(name)) WHERE (parent_id IS NULL);


--
-- Name: uq_primary_artifact_per_owner; Type: INDEX; Schema: app; Owner: -
--

CREATE UNIQUE INDEX uq_primary_artifact_per_owner ON app.artifacts USING btree (owner_type_code, owner_id) WHERE ((is_primary = true) AND (status <> 'ARCHIVED'::app.artifact_status));


--
-- Name: uq_training_datasets_type_name; Type: INDEX; Schema: app; Owner: -
--

CREATE UNIQUE INDEX uq_training_datasets_type_name ON app.training_datasets USING btree (dataset_type_id, name) WHERE (archived_at IS NULL);


