-- Database roles per doc 03 section 40 and doc 18 section 8.1 (historical
-- reference only — see AGENTS.md). Passwords are NOT set here; they are
-- injected at deploy time via `ALTER ROLE <role> PASSWORD ...` from env /
-- secret manager. The migration_role (superuser used to run migrations)
-- already exists.

-- Idempotent role creation (LOGIN roles, no password until deploy sets one).
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'backend_role') THEN
        CREATE ROLE backend_role LOGIN;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'scheduler_role') THEN
        CREATE ROLE scheduler_role LOGIN;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'worker_role') THEN
        CREATE ROLE worker_role LOGIN;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'readonly_role') THEN
        CREATE ROLE readonly_role LOGIN;
    END IF;
END $$;

